const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcano = ee.Geometry.Point([122.775, -8.542]); // Mount Lewotobi Laki-Laki
  const region = volcano.buffer(50000); // 50 km buffer for analysis
  const date = '2025-07-07';
  const startTime = ee.Date(date + 'T05:00:00'); // 05:00 UTC = 13:00 local
  const endTime = ee.Date(date + 'T07:00:00');   // 07:00 UTC = 15:00 local

  // Collections to try (ordered by relevance for afternoon overpass)
  const collections = [
    { name: 'MODIS Aqua', id: 'MODIS/006/MYD09GA' },
    { name: 'VIIRS', id: 'NOAA/VIIRS/001/VNP09GA' },
    { name: 'MODIS Terra', id: 'MODIS/006/MOD09GA' }
  ];

  let image = null;
  let collectionName = '';

  // 2. Data Acquisition & Check
  for (const col of collections) {
    const coll = ee.ImageCollection(col.id)
      .filterBounds(volcano)
      .filterDate(startTime, endTime)
      .select(['sur_refl_b01', 'sur_refl_b04', 'sur_refl_b03']); // RGB bands for MODIS/VIIRS
    const count = coll.size().getInfo();
    console.log(`${col.name} Images: ${count}`);
    if (count > 0) {
      image = coll.first();
      collectionName = col.name;
      break;
    }
  }

  if (!image) {
    console.log('No images found in any collection for the specified time and location.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing: Check valid pixels
  const redBand = image.select(0); // First band (sur_refl_b01 for MODIS, similar for VIIRS)
  const countResult = redBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });
  const pixelCount = countResult.getInfo()[Object.keys(countResult.getInfo())[0]];
  console.log(`Valid pixels in region: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Attempt plume detection and direction analysis
  // Simple threshold for bright pixels (potential plume)
  const threshold = 0.2; // Reflectance threshold
  const plumeMask = redBand.gt(threshold);

  // Get centroid of bright pixels
  const centroid = plumeMask.reduceRegion({
    reducer: ee.Reducer.centroid(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  if (!centroid || Object.keys(centroid).length === 0) {
    console.log('Could not compute centroid (no bright pixels).');
    console.log('<answer>C3</answer>');
    return;
  }

  // Extract centroid coordinates (lon, lat)
  const centroidCoords = centroid[Object.keys(centroid)[0]];
  const centroidLon = centroidCoords['coordinates'][0];
  const volcanoLon = 122.775;

  console.log(`Volcano longitude: ${volcanoLon}`);
  console.log(`Plume centroid longitude: ${centroidLon}`);

  // 5. Determine if plume is westward
  const tolerance = 0.01; // Degrees
  if (centroidLon < volcanoLon - tolerance) {
    console.log('Plume centroid is west of volcano -> drifting westward.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Plume centroid is not west of volcano.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
